const post = $json;
const WP_CATEGORIES = {'Breaking News': 1, 'Iron Ore News': 163, 'Steel News': 175, 'Metals News': 176};
const WP_TAGS = {'iron-ore': 165, 'iodex': 166, 'china': 167, 'brazil-miners': 168, 'global-miners': 169, 'freight': 170, 'steel': 171, 'market-analysis': 172, 'price-alert': 173, 'weekly-report': 174};
let cleanHtml = post.content_html || '';
cleanHtml = cleanHtml.replace(/<div class="post-metadata">[\s\S]*?<\/div>/gi, '').trim();
const wpCategoryNames = [];
const dbCategories = Array.isArray(post.categories) ? post.categories : [];
if (post.tier === 'TIER_1') wpCategoryNames.push('Breaking News');
dbCategories.forEach(cat => { const catLower = cat.toLowerCase(); if (catLower.includes('china') || catLower.includes('demanda') || catLower.includes('preco') || catLower.includes('spot')) { if (!wpCategoryNames.includes('Iron Ore News')) wpCategoryNames.push('Iron Ore News'); } if (catLower.includes('siderur') || catLower.includes('steel') || catLower.includes('aco')) { if (!wpCategoryNames.includes('Steel News')) wpCategoryNames.push('Steel News'); } });
if (wpCategoryNames.length === 0) wpCategoryNames.push('Iron Ore News');
const wpCategoryIds = wpCategoryNames.map(name => WP_CATEGORIES[name]).filter(id => id);
const wpTagSlugs = [];
const dbTags = Array.isArray(post.tags) ? post.tags : [];
dbTags.forEach(tag => { const tagLower = tag.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9-]/g, ''); if (tagLower.includes('minerio') || tagLower.includes('iron')) { if (!wpTagSlugs.includes('iron-ore')) wpTagSlugs.push('iron-ore'); } if (tagLower.includes('iodex') || tagLower.includes('platts')) { if (!wpTagSlugs.includes('iodex')) wpTagSlugs.push('iodex'); } if (tagLower.includes('china')) { if (!wpTagSlugs.includes('china')) wpTagSlugs.push('china'); } if (tagLower.includes('vale') || tagLower.includes('csn')) { if (!wpTagSlugs.includes('brazil-miners')) wpTagSlugs.push('brazil-miners'); } if (tagLower.includes('bhp') || tagLower.includes('rio')) { if (!wpTagSlugs.includes('global-miners')) wpTagSlugs.push('global-miners'); } });
if (wpTagSlugs.length === 0) wpTagSlugs.push('iron-ore');
const wpTagIds = wpTagSlugs.map(slug => WP_TAGS[slug]).filter(id => id);
const slug = post.slug || post.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').substring(0, 50);
return { wp_title: post.title, wp_content: cleanHtml, wp_slug: slug, wp_excerpt: post.excerpt || '', wp_categories: wpCategoryIds, wp_tags: wpTagIds, wp_category_names: wpCategoryNames, wp_tag_slugs: wpTagSlugs, post_id: post.id, original_title: post.title, original_content: cleanHtml, tier: post.tier };

const aiResponse = $json;
const prepData = $('PREPARAR DADOS POST').item.json;
const imagePrompt = aiResponse.text || aiResponse.output || aiResponse.response || '';
const timestamp = Date.now();
const imageFilename = prepData.wp_title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 50) + '-' + timestamp + '.png';
const storagePath = `editorial/${prepData.post_id}/${imageFilename}`;
return { ...prepData, image_prompt: imagePrompt, image_filename: imageFilename, storage_path: storagePath, image_alt_text: prepData.wp_title };

const prepData = $('PREPARAR PROMPT GEMINI').item.json;
const imageUrl = `https://pbhvhfahcvgmgjvuhwuk.supabase.co/storage/v1/object/public/social-images/${prepData.storage_path}`;
return { ...prepData, image_url: imageUrl };

const data = $('CONSTRUIR URL IMAGEM').item.json;
const imageRecord = $json;
const excerpt = data.original_content.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().substring(0, 200) + '...';
const caption = `🖼 *PREVIEW - APROVAR IMAGEM*
━━━━━━━━━━━━━━━━━━━━━

📝 *${data.wp_title}*

📄 ${excerpt}

📁 Categorias: ${data.wp_category_names.join(', ')}
🏷 Tags: ${data.wp_tag_slugs.join(', ')}

━━━━━━━━━━━━━━━━━━━━━
⏳ Aguardando aprovação da imagem`;
const inlineKeyboard = { inline_keyboard: [[{ text: '✅ Publicar', callback_data: `publish_${data.post_id}` }, { text: '🔄 Nova Imagem', callback_data: `regen_${data.post_id}` }], [{ text: '❌ Cancelar', callback_data: `cancel_${data.post_id}` }]] };
return { chat_id: '8375309778', photo_url: data.image_url, caption: caption, parse_mode: 'Markdown', reply_markup: JSON.stringify(inlineKeyboard), post_id: data.post_id, image_record_id: imageRecord.id };
